  const ocho = [[2,900],[3,1000],[2,300],[4,250],[10,950],[11,1050],[12,280],[9,320]];
  const g = K.rng(7), mil = [];
  [[3,950],[3,280],[10.5,1000],[10.5,300]].forEach(([v, t]) => {
    for (let i = 0; i < 30; i++) mil.push([Math.max(0.5, +(v + 1.1 * g.normal()).toFixed(1)), Math.max(60, Math.round(t + 75 * g.normal()))]);
  });
  const SETS = { ocho, mil };
